import React, { PropsWithChildren } from 'react';
import styled from 'styled-components';

import {
  GLOBAL_VALUE_FONT_CSS_TOKEN,
  GLOBAL_TREND_FONT_CSS_TOKEN,
  GLOBAL_LABEL_FONT_CSS_TOKEN,
} from '../constants.js';
import { useGlobalFontSize } from '../hooks/use-global-font-size.js';

const CSSVariableHolder = styled('div').attrs<{
  valueFontSize?: number;
  labelFontSize?: number;
  trendFontSize?: number;
}>(({ valueFontSize, labelFontSize, trendFontSize }) => ({
  style: {
    [GLOBAL_VALUE_FONT_CSS_TOKEN]: valueFontSize,
    [GLOBAL_LABEL_FONT_CSS_TOKEN]: labelFontSize,
    [GLOBAL_TREND_FONT_CSS_TOKEN]: trendFontSize,
  },
}))<{
  valueFontSize?: number;
  labelFontSize?: number;
  trendFontSize?: number;
}>({
  width: '100%',
  height: '100%',
  overflow: 'hidden',
});

/** A wrapper that holds the runtime css token variables of the global font size, to be accessed by child SingleValue components */
export const GlobalFontSizeVariables = ({ children }: PropsWithChildren) => {
  const { valueFontSize, labelFontSize, trendFontSize } = useGlobalFontSize();

  return (
    <CSSVariableHolder
      data-testid={'global-font-size-variables'}
      valueFontSize={valueFontSize}
      labelFontSize={labelFontSize}
      trendFontSize={trendFontSize}
    >
      {children}
    </CSSVariableHolder>
  );
};
